import { describe, expect, it } from 'vitest'

import { audit, directory, toRecord } from '../lib/server/partnerTrust'
import cases from './fixtures/partner-trust-parity.json'

// Generated by backend/scripts/export_trust_parity.py from the Python implementation.
type Case = { row: Record<string, any>; expected: Record<string, any> }
const all = cases as Case[]

// What Supabase's Data API returns: numeric(5,2) arrives as a JSON number.
const asSupabaseRow = (row: Record<string, any>) => ({
  ...row,
  financial_solvency_score: row.financial_solvency_score == null ? null : Number(row.financial_solvency_score),
  litigation_flag: false,
  updated_at: '2026-10-24T00:00:00Z',
})

describe('Japan-Readiness & Trust Score parity with Python', () => {
  it.each(all.map((c) => [c.row.partner_name, c] as const))('%s', (_name, c) => {
    for (const row of [c.row, asSupabaseRow(c.row)]) {
      const { record: _record, computed_at: _at, ...got } = audit(toRecord(row), new Date('2026-10-24T00:00:00Z'))
      const { evidence, ...expected } = c.expected
      expect({ ...got, evidence }).toEqual({ ...expected, evidence })
      expect(got.components.map((x) => x.reasons)).toEqual(expected.components.map((x: any) => x.reasons))
    }
  })

  it('directory filters and ordering match the service contract', () => {
    const records = all.map((c) => toRecord(c.row))
    const full = directory(records, {})
    expect(full.partners.map((p) => p.score)).toEqual([...full.partners.map((p) => p.score)].sort((a, b) => Number(b) - Number(a)))
    expect(directory(records, { state: 'gujarat' }).partners.every((p) => p.state === 'Gujarat')).toBe(true)
    const strong = directory(records, { minTrustScore: '80' }).partners
    expect(strong.length).toBeGreaterThan(0)
    expect(strong.every((p) => Number(p.score) >= 80 && p.tier !== 'blocked')).toBe(true)
    expect(directory(records, { minOtd: '95' }).partners.every((p) => Number(p.otd_trailing_pct) >= 95)).toBe(true)
    expect(full.partners.find((p) => p.partner_name.startsWith('Yamuna'))?.litigation_flag).toBe(true)
  })
})
